/**
 * Grounded marketing copy. Every line traces to the real Third Eye Kit v2
 * dossier (see docs/instructions/ and the third-eye-kit-v2 repo). No filler,
 * no invented claims, and no em-dashes.
 */

export const brand = {
  name: "Third Eye",
  world: "Third Eye World",
  tagline: "Feel, don't wait.",
  mission: "They deserve more.",
} as const;

export const hero = {
  kicker: "Assistive technology for the traveler who was overlooked.",
  headline: "A blind person should feel the world in real time.",
  sub: "Third Eye delivers the world into the body, by feel, the instant it matters.",
  primaryCta: { label: "Join the Commons", href: "/app/signup" },
  secondaryCta: { label: "How it works", href: "#how" },
} as const;

export const oneIdea = {
  heading: "Everyone builds the eyes. We build the way in.",
  body: "Almost everyone builds the robot eyes: a camera and an AI. Almost no one builds the human input channel, how the information actually reaches the person fast enough to act on. That channel, a full-body buzz-language and a gently-steering exoskeleton, is what Third Eye invents.",
} as const;

export const pillars = [
  {
    key: "senses",
    title: "Senses",
    body: "Direct physical measurement, never guesswork. Time-of-flight lasers, radar, ultrasonic, and sensors in the hands and feet.",
  },
  {
    key: "delivers",
    title: "Delivers",
    body: "The world reaches the body instantly, through full-body vibration and a gently-steering exoskeleton. You feel it before a voice could finish a sentence.",
  },
  {
    key: "assists",
    title: "Assists",
    body: "An AI reads signs, names things, and helps with routes. It never becomes the eyes, and it never steers.",
  },
] as const;

export const rules = [
  "Life-critical sensing and steering is physics, not AI inference.",
  "The AI is an assistant only. It never becomes the eyes and never steers.",
  "The exoskeleton warns, then gently steers, and never locks.",
  "Fail transparent. On any fault the motors freewheel and never trap a limb.",
  "Augment, do not replace, the white cane and the user's own hearing.",
] as const;

export const safety = {
  heading: "The honest version.",
  body: "v1 is a tested prototype. v2, the powered exoskeleton and the health and hot-surface features, is a design and reference specification: a blueprint, not a finished or certified product. It must pass staged safety validation before anyone relies on it. The white cane and your own hearing stay primary. This system augments them. It does not replace them.",
} as const;

export const person = {
  name: "Said Mohaddes Sadeqi",
  role: "Project lead and engineer",
  place: "Hillsboro, Oregon",
  quote:
    "Blind travelers have been handed a pile of tools that don't work together and aren't safe on a real road. This is built for the capable, long-overlooked traveler.",
} as const;

export const finalCta = {
  heading: "Join the people building it.",
  body: "Third Eye Commons is where blind travelers, families, clinicians, engineers, and supporters follow the work, join the pilot, and take part.",
  cta: { label: "Join the Commons", href: "/app/signup" },
} as const;

export const nav = {
  links: [
    { label: "How it works", href: "#how" },
    { label: "The rules", href: "#rules" },
    { label: "Safety", href: "#safety" },
  ],
  cta: { label: "Join the Commons", href: "/app/signup" },
} as const;

