/**
 * The buzz-language: how the world reaches the body by feel. Pure data + helpers
 * so the interactive demo (and its tests) share one source of truth. Grounded in
 * the dossier's haptic body map and sensing model.
 */

export type BodyZone =
  | "torso"
  | "leftArm"
  | "rightArm"
  | "hands"
  | "feet";

export type Urgency = "low" | "medium" | "high";

export interface BuzzScenario {
  id: string;
  label: string;
  /** Spoken/announced description of what the body feels. */
  description: string;
  /** Body zones that vibrate. */
  zones: BodyZone[];
  /** Vibration timeline in milliseconds: [on, off, on, off, ...]. */
  pattern: number[];
  /** Audio proxy so sighted and Deaf-blind users perceive the same signal. */
  tone: { frequency: number; pulses: number; urgency: Urgency };
}

export const scenarios: BuzzScenario[] = [
  {
    id: "obstacle",
    label: "Obstacle ahead",
    description:
      "Obstacle ahead. A firm, steady buzz spreads across the front of the torso and grows stronger as it comes closer.",
    zones: ["torso"],
    pattern: [140, 70, 140, 70, 240],
    tone: { frequency: 200, pulses: 3, urgency: "high" },
  },
  {
    id: "dropoff",
    label: "Drop-off underfoot",
    description:
      "A drop-off at your feet. A sharp double tap routes to the zones nearest the soles, telling you to stop.",
    zones: ["feet"],
    pattern: [60, 40, 60],
    tone: { frequency: 150, pulses: 2, urgency: "high" },
  },
  {
    id: "openLeft",
    label: "Path opens left",
    description:
      "The path opens to your left. A soft, slow pulse drifts to the left side, inviting you to move that way.",
    zones: ["leftArm"],
    pattern: [200, 130, 200],
    tone: { frequency: 340, pulses: 2, urgency: "low" },
  },
  {
    id: "hotSurface",
    label: "Hot surface near hand",
    description:
      "A hot surface near your hand. A fast, urgent stutter on the hand pulls it back before you touch.",
    zones: ["hands"],
    pattern: [40, 30, 40, 30, 40, 30, 40],
    tone: { frequency: 110, pulses: 4, urgency: "high" },
  },
];

export function getScenario(id: string): BuzzScenario | undefined {
  return scenarios.find((s) => s.id === id);
}

/** Total time the pattern plays, in ms (sum of on + off segments). */
export function patternDuration(pattern: number[]): number {
  return pattern.reduce((total, ms) => total + ms, 0);
}

/** Number of "on" pulses in a pattern (even indices are on-segments). */
export function pulseCount(pattern: number[]): number {
  return pattern.filter((_, i) => i % 2 === 0).length;
}

