import { describe, it, expect } from "vitest";
import {
  scenarios,
  getScenario,
  patternDuration,
  pulseCount,
} from "@/lib/haptics/buzz-language";

describe("buzz-language", () => {
  it("defines scenarios with a valid shape", () => {
    expect(scenarios.length).toBeGreaterThan(0);
    for (const s of scenarios) {
      expect(s.id).toBeTruthy();
      expect(s.zones.length).toBeGreaterThan(0);
      expect(s.pattern.length).toBeGreaterThan(0);
      expect(s.pattern.every((n) => n > 0)).toBe(true);
      expect(s.description.length).toBeGreaterThan(10);
      expect(s.tone.pulses).toBeGreaterThan(0);
    }
  });

  it("looks scenarios up by id", () => {
    expect(getScenario("obstacle")?.id).toBe("obstacle");
    expect(getScenario("does-not-exist")).toBeUndefined();
  });

  it("sums the vibration timeline", () => {
    expect(patternDuration([140, 70, 140, 70, 240])).toBe(660);
    expect(patternDuration([])).toBe(0);
  });

  it("counts on-segments as pulses", () => {
    expect(pulseCount([140, 70, 140, 70, 240])).toBe(3);
    expect(pulseCount([60, 40, 60])).toBe(2);
  });
});

