"use client";

import { useCallback, useRef, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { SpeakerHigh, SpeakerSlash } from "@phosphor-icons/react";
import {
  scenarios,
  getScenario,
  patternDuration,
  type BodyZone,
} from "@/lib/haptics/buzz-language";

// A body figure built from primitives, matching the dossier's own body-map
// construction. Each zone is addressable so a signal can light it up.
const ZONE_LABEL: Record<BodyZone, string> = {
  torso: "torso",
  leftArm: "left arm",
  rightArm: "right arm",
  hands: "hands",
  feet: "feet",
};

function playTone(
  ctx: AudioContext,
  tone: { frequency: number; pulses: number },
) {
  const now = ctx.currentTime;
  for (let i = 0; i < tone.pulses; i++) {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = "sine";
    osc.frequency.value = tone.frequency;
    const start = now + i * 0.18;
    gain.gain.setValueAtTime(0.0001, start);
    gain.gain.exponentialRampToValueAtTime(0.14, start + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.15);
    osc.connect(gain).connect(ctx.destination);
    osc.start(start);
    osc.stop(start + 0.17);
  }
}

export function HapticDemo() {
  const reduce = useReducedMotion();
  const [activeId, setActiveId] = useState<string | null>(null);
  const [message, setMessage] = useState(
    "Pick a signal. You will feel it, hear it, and see it at once.",
  );
  const [muted, setMuted] = useState(false);
  const audioRef = useRef<AudioContext | null>(null);
  const clearRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const active = activeId ? getScenario(activeId) : undefined;
  const activeZones = active?.zones ?? [];

  const trigger = useCallback(
    (id: string) => {
      const scenario = getScenario(id);
      if (!scenario) return;

      setActiveId(id);
      setMessage(scenario.description);

      // Real haptics where the browser supports it.
      if (typeof navigator !== "undefined" && "vibrate" in navigator) {
        navigator.vibrate(scenario.pattern);
      }

      // Audio proxy so the signal is perceivable without a vibration motor.
      if (!muted) {
        try {
          const AC =
            window.AudioContext ||
            (window as unknown as { webkitAudioContext: typeof AudioContext })
              .webkitAudioContext;
          audioRef.current ??= new AC();
          if (audioRef.current.state === "suspended") {
            void audioRef.current.resume();
          }
          playTone(audioRef.current, scenario.tone);
        } catch {
          // Audio is an enhancement; never let it break the interaction.
        }
      }

      if (clearRef.current) clearTimeout(clearRef.current);
      clearRef.current = setTimeout(
        () => setActiveId(null),
        Math.max(900, patternDuration(scenario.pattern) + 400),
      );
    },
    [muted],
  );

  const zoneFill = (zone: BodyZone) =>
    activeZones.includes(zone) ? "var(--accent)" : "var(--surface-2)";

  const Zone = ({
    zone,
    children,
  }: {
    zone: BodyZone;
    children: React.ReactNode;
  }) => {
    const isActive = activeZones.includes(zone);
    return (
      <motion.g
        style={{ fill: zoneFill(zone), stroke: "var(--border)" }}
        animate={
          isActive && !reduce ? { opacity: [1, 0.45, 1] } : { opacity: 1 }
        }
        transition={
          isActive && !reduce
            ? { duration: 0.5, repeat: Infinity, ease: "easeInOut" }
            : { duration: 0.2 }
        }
      >
        {children}
      </motion.g>
    );
  };

  return (
    <figure className="rounded-3xl border border-border bg-surface p-5 sm:p-6">
      <figcaption className="mb-4 flex items-center justify-between gap-3">
        <span className="text-sm font-medium text-fg">The buzz-language</span>
        <button
          type="button"
          onClick={() => setMuted((m) => !m)}
          aria-pressed={muted}
          className="inline-flex items-center gap-1.5 rounded-full border border-border px-3 py-1.5 text-xs text-muted transition-colors hover:text-fg"
        >
          {muted ? <SpeakerSlash size={16} /> : <SpeakerHigh size={16} />}
          {muted ? "Sound off" : "Sound on"}
        </button>
      </figcaption>

      <div className="grid gap-5 sm:grid-cols-[auto_1fr] sm:items-center">
        {/* Body figure */}
        <svg
          viewBox="0 0 120 210"
          role="img"
          aria-label="A body. Signals light up the zone you would feel."
          className="mx-auto h-52 w-auto"
          strokeWidth={1.5}
        >
          {/* head (static) */}
          <g style={{ fill: "var(--surface-2)", stroke: "var(--border)" }}>
            <circle cx="60" cy="20" r="13" strokeWidth={1.5} />
          </g>
          <Zone zone="leftArm">
            <rect x="26" y="44" width="12" height="54" rx="6" strokeWidth={1.5} />
          </Zone>
          <Zone zone="rightArm">
            <rect x="82" y="44" width="12" height="54" rx="6" strokeWidth={1.5} />
          </Zone>
          <Zone zone="torso">
            <rect x="42" y="40" width="36" height="64" rx="10" strokeWidth={1.5} />
          </Zone>
          <Zone zone="hands">
            <circle cx="32" cy="104" r="6" strokeWidth={1.5} />
            <circle cx="88" cy="104" r="6" strokeWidth={1.5} />
          </Zone>
          {/* legs (static) */}
          <g style={{ fill: "var(--surface-2)", stroke: "var(--border)" }}>
            <rect x="46" y="108" width="12" height="74" rx="6" strokeWidth={1.5} />
            <rect x="62" y="108" width="12" height="74" rx="6" strokeWidth={1.5} />
          </g>
          <Zone zone="feet">
            <rect x="42" y="184" width="18" height="10" rx="3" strokeWidth={1.5} />
            <rect x="60" y="184" width="18" height="10" rx="3" strokeWidth={1.5} />
          </Zone>
        </svg>

        {/* Controls */}
        <div>
          <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
            {scenarios.map((s) => (
              <button
                key={s.id}
                type="button"
                onClick={() => trigger(s.id)}
                aria-pressed={activeId === s.id}
                className={`rounded-xl border px-3 py-2.5 text-left text-sm transition-colors ${
                  activeId === s.id
                    ? "border-accent bg-accent/10 text-fg"
                    : "border-border text-muted hover:border-accent/60 hover:text-fg"
                }`}
              >
                {s.label}
              </button>
            ))}
          </div>

          <p
            aria-live="polite"
            className="mt-4 min-h-[3.5rem] text-sm leading-relaxed text-muted"
          >
            {message}
            {active ? (
              <span className="sr-only">
                {" "}
                You would feel this in the {active.zones.map((z) => ZONE_LABEL[z]).join(" and ")}.
              </span>
            ) : null}
          </p>
        </div>
      </div>
    </figure>
  );
}

