import Link from "next/link";
import { hero } from "@/lib/content/dossier";
import { HapticDemo } from "./haptic-demo";

// Rendered static (no scroll-reveal) so the above-the-fold value prop paints
// immediately: best LCP and instantly readable.
export function Hero() {
  return (
    <section className="relative overflow-hidden">
      <div className="mx-auto grid max-w-6xl gap-12 px-5 pb-20 pt-16 md:min-h-[calc(100dvh-4rem)] md:grid-cols-2 md:items-center md:gap-10 md:pt-20">
        <div>
          <p className="text-sm font-medium text-accent-strong">
            {hero.kicker}
          </p>
          <h1 className="mt-4 text-balance text-4xl font-semibold leading-[1.05] tracking-tight sm:text-5xl lg:text-[3.5rem]">
            {hero.headline}
          </h1>
          <p className="mt-5 max-w-md text-lg leading-relaxed text-muted">
            {hero.sub}
          </p>
          <div className="mt-8 flex flex-wrap items-center gap-3">
            <Link
              href={hero.primaryCta.href}
              className="rounded-full bg-accent px-5 py-3 font-medium text-accent-fg transition-transform active:translate-y-px"
            >
              {hero.primaryCta.label}
            </Link>
            <Link
              href={hero.secondaryCta.href}
              className="rounded-full border border-border px-5 py-3 font-medium text-fg transition-colors hover:bg-surface-2"
            >
              {hero.secondaryCta.label}
            </Link>
          </div>
        </div>

        <div className="md:max-w-md md:justify-self-end">
          <HapticDemo />
        </div>
      </div>
    </section>
  );
}

