"use client";

import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";
import { type A11yPrefs } from "@/lib/a11y";
import { updateA11yPrefs } from "@/actions/profile";

type A11yContextValue = {
  prefs: A11yPrefs;
  update: (patch: Partial<A11yPrefs>) => void;
};

const A11yContext = createContext<A11yContextValue | null>(null);

export function A11yProvider({
  initial,
  children,
}: {
  initial: A11yPrefs;
  children: ReactNode;
}) {
  const [prefs, setPrefs] = useState<A11yPrefs>(initial);

  useEffect(() => {
    const el = document.documentElement;
    el.dataset.reducedMotion = prefs.reducedMotion ? "true" : "false";
    if (prefs.highContrast) {
      el.dataset.contrast = "high";
    } else {
      el.removeAttribute("data-contrast");
    }
    el.style.setProperty("--text-scale", String(prefs.textScale));
  }, [prefs]);

  const update = (patch: Partial<A11yPrefs>) => {
    setPrefs((prev) => {
      const next = { ...prev, ...patch };
      // Persist in the background; the visual change is already applied.
      void updateA11yPrefs(next);
      return next;
    });
  };

  return (
    <A11yContext.Provider value={{ prefs, update }}>
      {children}
    </A11yContext.Provider>
  );
}

export function useA11y(): A11yContextValue {
  const ctx = useContext(A11yContext);
  if (!ctx) throw new Error("useA11y must be used within an A11yProvider");
  return ctx;
}

