"use client";

import { TEXT_SCALES } from "@/lib/a11y";
import { useA11y } from "./a11y-provider";

export function A11yControls() {
  const { prefs, update } = useA11y();

  return (
    <div className="flex flex-col gap-6">
      <div className="flex flex-col gap-3">
        <label className="flex items-center justify-between gap-4">
          <span>
            <span className="block font-medium text-fg">Reduce motion</span>
            <span className="block text-sm text-muted">
              Turn off animation and movement across the app.
            </span>
          </span>
          <input
            type="checkbox"
            checked={prefs.reducedMotion}
            onChange={(e) => update({ reducedMotion: e.target.checked })}
            className="size-5 accent-[var(--accent)]"
          />
        </label>

        <label className="flex items-center justify-between gap-4">
          <span>
            <span className="block font-medium text-fg">High contrast</span>
            <span className="block text-sm text-muted">
              Stronger borders and text for easier reading.
            </span>
          </span>
          <input
            type="checkbox"
            checked={prefs.highContrast}
            onChange={(e) => update({ highContrast: e.target.checked })}
            className="size-5 accent-[var(--accent)]"
          />
        </label>
      </div>

      <fieldset>
        <legend className="font-medium text-fg">Text size</legend>
        <div
          role="radiogroup"
          aria-label="Text size"
          className="mt-2 inline-flex rounded-lg border border-border p-1"
        >
          {TEXT_SCALES.map((t) => (
            <button
              key={t.value}
              type="button"
              role="radio"
              aria-checked={prefs.textScale === t.value}
              onClick={() => update({ textScale: t.value })}
              className={`rounded-md px-3 py-1.5 text-sm transition-colors ${
                prefs.textScale === t.value
                  ? "bg-accent text-accent-fg"
                  : "text-muted hover:text-fg"
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>
      </fieldset>
    </div>
  );
}

