"use server";

import { revalidatePath } from "next/cache";
import { auth } from "@/lib/auth";
import { prisma } from "@/lib/db";

export type ReactionResult =
  | { count: number; reacted: boolean }
  | { error: string };

export async function toggleReaction(
  updateId: string,
): Promise<ReactionResult> {
  const session = await auth();
  if (!session?.user) return { error: "You are not signed in." };
  const userId = session.user.id;

  const existing = await prisma.reaction.findUnique({
    where: { updateId_userId: { updateId, userId } },
  });
  if (existing) {
    await prisma.reaction.delete({ where: { id: existing.id } });
  } else {
    await prisma.reaction.create({
      data: { updateId, userId, kind: "support" },
    });
  }

  const count = await prisma.reaction.count({ where: { updateId } });
  revalidatePath("/app/feed");
  return { count, reacted: !existing };
}

