"use client";

import { useState, useTransition } from "react";
import { Heart } from "@phosphor-icons/react";
import { toggleReaction } from "@/actions/feed";

export function ReactionButton({
  updateId,
  initialCount,
  initialReacted,
}: {
  updateId: string;
  initialCount: number;
  initialReacted: boolean;
}) {
  const [count, setCount] = useState(initialCount);
  const [reacted, setReacted] = useState(initialReacted);
  const [pending, startTransition] = useTransition();

  const onClick = () =>
    startTransition(async () => {
      const res = await toggleReaction(updateId);
      if ("count" in res) {
        setCount(res.count);
        setReacted(res.reacted);
      }
    });

  return (
    <button
      type="button"
      onClick={onClick}
      disabled={pending}
      aria-pressed={reacted}
      className={`inline-flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-sm transition-colors disabled:opacity-60 ${
        reacted
          ? "border-accent text-accent-strong"
          : "border-border text-muted hover:text-fg"
      }`}
    >
      <Heart size={16} weight={reacted ? "fill" : "regular"} aria-hidden />
      <span>{count}</span>
      <span className="sr-only">
        {reacted ? "supporters. Remove your support" : "supporters. Add your support"}
      </span>
    </button>
  );
}

