"use client";

import { useActionState } from "react";
import { joinWaitlist, type ActionState } from "@/actions/waitlist";

const INPUT =
  "rounded-md border border-border bg-transparent px-3 py-2 focus-visible:border-accent";

export function WaitlistForm({
  initial,
}: {
  initial: { region: string; deviceContext: string } | null;
}) {
  const [state, action, pending] = useActionState(
    joinWaitlist,
    {} as ActionState,
  );

  return (
    <form action={action} className="mt-8 flex max-w-lg flex-col gap-4">
      <div className="flex flex-col gap-1.5">
        <label htmlFor="region" className="text-sm font-medium">
          Where do you travel? <span className="text-muted">(optional)</span>
        </label>
        <input
          id="region"
          name="region"
          defaultValue={initial?.region ?? ""}
          className={INPUT}
        />
      </div>

      <div className="flex flex-col gap-1.5">
        <label htmlFor="deviceContext" className="text-sm font-medium">
          Anything about your current tools or needs?{" "}
          <span className="text-muted">(optional)</span>
        </label>
        <textarea
          id="deviceContext"
          name="deviceContext"
          rows={4}
          defaultValue={initial?.deviceContext ?? ""}
          className={INPUT}
        />
      </div>

      {state.error ? (
        <p role="alert" aria-live="assertive" className="text-sm text-red-600">
          {state.error}
        </p>
      ) : null}
      {state.ok ? (
        <p role="status" aria-live="polite" className="text-sm text-accent-strong">
          Saved. You are on the pilot waitlist.
        </p>
      ) : null}

      <button
        type="submit"
        disabled={pending}
        className="self-start rounded-full bg-accent px-5 py-2.5 font-medium text-accent-fg disabled:opacity-60"
      >
        {pending ? "Saving…" : initial ? "Update my entry" : "Join the waitlist"}
      </button>
    </form>
  );
}

