"use client";

import { useActionState } from "react";
import {
  saveContributorInterest,
  type ActionState,
} from "@/actions/contribute";
import { FOCUS_AREAS } from "@/lib/validation";

const INPUT =
  "rounded-md border border-border bg-transparent px-3 py-2 focus-visible:border-accent";

export function ContributorForm({
  initial,
}: {
  initial: { githubUrl: string; focusAreas: string[]; note: string } | null;
}) {
  const [state, action, pending] = useActionState(
    saveContributorInterest,
    {} as ActionState,
  );

  return (
    <form action={action} className="mt-8 flex max-w-lg flex-col gap-6">
      <div className="flex flex-col gap-1.5">
        <label htmlFor="githubUrl" className="text-sm font-medium">
          Your GitHub or portfolio{" "}
          <span className="text-muted">(optional)</span>
        </label>
        <input
          id="githubUrl"
          name="githubUrl"
          type="url"
          inputMode="url"
          placeholder="https://github.com/you"
          defaultValue={initial?.githubUrl ?? ""}
          className={INPUT}
        />
      </div>

      <fieldset className="flex flex-col gap-2">
        <legend className="text-sm font-medium">Where can you help?</legend>
        {FOCUS_AREAS.map((f) => (
          <label key={f.value} className="flex items-center gap-3">
            <input
              type="checkbox"
              name="focusAreas"
              value={f.value}
              defaultChecked={initial?.focusAreas.includes(f.value) ?? false}
              className="size-5 accent-[var(--accent)]"
            />
            <span>{f.label}</span>
          </label>
        ))}
      </fieldset>

      <div className="flex flex-col gap-1.5">
        <label htmlFor="note" className="text-sm font-medium">
          Anything else? <span className="text-muted">(optional)</span>
        </label>
        <textarea
          id="note"
          name="note"
          rows={4}
          defaultValue={initial?.note ?? ""}
          className={INPUT}
        />
      </div>

      {state.error ? (
        <p role="alert" aria-live="assertive" className="text-sm text-red-600">
          {state.error}
        </p>
      ) : null}
      {state.ok ? (
        <p role="status" aria-live="polite" className="text-sm text-accent-strong">
          Thank you. Your interest is saved.
        </p>
      ) : null}

      <button
        type="submit"
        disabled={pending}
        className="self-start rounded-full bg-accent px-5 py-2.5 font-medium text-accent-fg disabled:opacity-60"
      >
        {pending ? "Saving…" : "Save my interest"}
      </button>
    </form>
  );
}

