            <input
              type="checkbox"
              name="focusAreas"
              value={f.value}
              defaultChecked={initial?.focusAreas.includes(f.value) ?? false}
              className="size-5 accent-[var(--accent)]"
            />
            <span>{f.label}</span>
          </label>
        ))}
      </fieldset>

      <div className="flex flex-col gap-1.5">
        <label htmlFor="note" className="text-sm font-medium">
          Anything else? <span className="text-muted">(optional)</span>
        </label>
        <textarea
          id="note"
          name="note"
          rows={4}
          defaultValue={initial?.note ?? ""}
          className={INPUT}
        />
      </div>

      {state.error ? (
        <p role="alert" aria-live="assertive" className="text-sm text-red-600">
          {state.error}
        </p>
      ) : null}
      {state.ok ? (
        <p role="status" aria-live="polite" className="text-sm text-accent-strong">
          Thank you. Your interest is saved.
        </p>
      ) : null}

      <button
        type="submit"
        disabled={pending}
        className="self-start rounded-full bg-accent px-5 py-2.5 font-medium text-accent-fg disabled:opacity-60"
      >
        {pending ? "Saving…" : "Save my interest"}
      </button>
    </form>
  );
}

