import { describe, it, expect } from "vitest";
import { normalizeA11yPrefs, DEFAULT_A11Y_PREFS } from "@/lib/a11y";

describe("normalizeA11yPrefs", () => {
  it("returns defaults for empty or garbage input", () => {
    expect(normalizeA11yPrefs(undefined)).toEqual(DEFAULT_A11Y_PREFS);
    expect(normalizeA11yPrefs(null)).toEqual(DEFAULT_A11Y_PREFS);
    expect(normalizeA11yPrefs("nope")).toEqual(DEFAULT_A11Y_PREFS);
  });

  it("coerces booleans and keeps an allowed text scale", () => {
    expect(
      normalizeA11yPrefs({
        reducedMotion: true,
        highContrast: 1,
        textScale: 1.15,
      }),
    ).toEqual({ reducedMotion: true, highContrast: true, textScale: 1.15 });
  });

  it("falls back to scale 1 for out-of-range values", () => {
    expect(normalizeA11yPrefs({ textScale: 3 }).textScale).toBe(1);
    expect(normalizeA11yPrefs({ textScale: "big" }).textScale).toBe(1);
  });
});

