import { describe, it, expect } from "vitest";
import {
  profileSchema,
  contributorSchema,
  waitlistSchema,
} from "@/lib/validation";

describe("profileSchema", () => {
  it("requires a display name", () => {
    expect(profileSchema.safeParse({ displayName: "" }).success).toBe(false);
    expect(profileSchema.safeParse({ displayName: "Ada" }).success).toBe(true);
  });

  it("treats empty optional fields as undefined", () => {
    const r = profileSchema.parse({ displayName: "Ada", bio: "", region: "" });
    expect(r.bio).toBeUndefined();
    expect(r.region).toBeUndefined();
  });
});

describe("waitlistSchema", () => {
  it("accepts empty optionals", () => {
    expect(waitlistSchema.safeParse({ region: "", deviceContext: "" }).success).toBe(
      true,
    );
  });
});

describe("contributorSchema", () => {
  it("accepts known focus areas and a valid url", () => {
    const r = contributorSchema.safeParse({
      githubUrl: "https://github.com/ada",
      focusAreas: ["haptics", "app"],
      note: "",
    });
    expect(r.success).toBe(true);
  });

  it("rejects an unknown focus area", () => {
    expect(
      contributorSchema.safeParse({ focusAreas: ["nope"] }).success,
    ).toBe(false);
  });

  it("rejects an invalid url", () => {
    expect(
      contributorSchema.safeParse({ githubUrl: "not-a-url", focusAreas: [] })
        .success,
    ).toBe(false);
  });
});

