import { test, expect } from "@playwright/test";

async function signUp(page: import("@playwright/test").Page) {
  const email = `commons-${Date.now()}-${Math.floor(performance.now())}@example.com`;
  await page.goto("/app/signup");
  await page.getByLabel("Name").fill("Ada Traveler");
  await page.getByLabel("Email").fill(email);
  await page.getByLabel("Password").fill("test-password-123");
  await page.getByLabel("I am a").selectOption("ENGINEER");
  await page.getByRole("button", { name: /create account/i }).click();
  await expect(page).toHaveURL(/\/app$/);
}

test("full Commons flow: feed, waitlist, contribute, dossier", async ({
  page,
}) => {
  await signUp(page);

  // Feed: support an update, then remove support
  await page.getByRole("link", { name: "Updates" }).first().click();
  await expect(page).toHaveURL(/\/app\/feed$/);
  const support = page
    .getByRole("button", { name: /add your support/i })
    .first();
  await support.click();
  await expect(
    page.getByRole("button", { name: /remove your support/i }).first(),
  ).toBeVisible();

  // Waitlist
  await page.getByRole("link", { name: "Pilot waitlist" }).first().click();
  await expect(page).toHaveURL(/\/app\/waitlist$/);
  await page.getByLabel(/where do you travel/i).fill("Portland, OR");
  await page.getByRole("button", { name: /join the waitlist/i }).click();
  await expect(page.getByText(/on the pilot waitlist/i)).toBeVisible();

  // Contribute
  await page.getByRole("link", { name: "Contribute" }).first().click();
  await expect(page).toHaveURL(/\/app\/contribute$/);
  await page.getByRole("checkbox", { name: /haptics/i }).check();
  await page.getByRole("button", { name: /save my interest/i }).click();
  await expect(page.getByText(/your interest is saved/i)).toBeVisible();

  // Dossier
  await page.getByRole("link", { name: "Dossier" }).first().click();
  await expect(
    page.getByRole("heading", { name: /the third eye dossier/i }),
  ).toBeVisible();
});

test("accessibility preferences apply and persist across reload", async ({
  page,
}) => {
  await signUp(page);
  await page.getByRole("link", { name: "Profile" }).first().click();
  await expect(page).toHaveURL(/\/app\/profile$/);

  await page.getByLabel(/high contrast/i).check();
  await expect(page.locator("html")).toHaveAttribute("data-contrast", "high");

  // give the background persist a moment, then reload
  await page.waitForTimeout(800);
  await page.reload();
  await expect(page.locator("html")).toHaveAttribute("data-contrast", "high");
});

