"use server";

import { revalidatePath } from "next/cache";
import { auth } from "@/lib/auth";
import { prisma } from "@/lib/db";
import { profileSchema } from "@/lib/validation";
import { normalizeA11yPrefs, type A11yPrefs } from "@/lib/a11y";

export type ActionState = { ok?: boolean; error?: string };

export async function updateProfile(
  _prev: ActionState,
  formData: FormData,
): Promise<ActionState> {
  const session = await auth();
  if (!session?.user) return { error: "You are not signed in." };

  const parsed = profileSchema.safeParse({
    displayName: formData.get("displayName"),
    bio: formData.get("bio"),
    region: formData.get("region"),
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Please check the form." };
  }

  await prisma.profile.update({
    where: { userId: session.user.id },
    data: {
      displayName: parsed.data.displayName,
      bio: parsed.data.bio ?? null,
      region: parsed.data.region ?? null,
    },
  });
  revalidatePath("/app/profile");
  return { ok: true };
}

export async function updateA11yPrefs(prefs: A11yPrefs): Promise<void> {
  const session = await auth();
  if (!session?.user) return;
  await prisma.profile.update({
    where: { userId: session.user.id },
    data: { a11yPrefs: normalizeA11yPrefs(prefs) },
  });
}

