import { test, expect } from "@playwright/test";
import AxeBuilder from "@axe-core/playwright";

// The marketing home and all five authed Commons routes are audited in
// marketing.a11y.spec.ts and commons.a11y.spec.ts. This file adds the public
// app pages plus structural + keyboard checks across public routes.

const PUBLIC_PATHS = ["/", "/app/login", "/app/signup"];

for (const path of ["/app/login", "/app/signup"]) {
  test(`no serious or critical a11y violations: ${path}`, async ({ page }) => {
    await page.emulateMedia({ reducedMotion: "reduce" });
    await page.goto(path);
    const results = await new AxeBuilder({ page })
      .withTags(["wcag2a", "wcag2aa", "wcag21a", "wcag21aa"])
      .analyze();
    const blocking = results.violations.filter(
      (v) => v.impact === "serious" || v.impact === "critical",
    );
    expect(
      blocking,
      JSON.stringify(
        blocking.map((v) => ({ id: v.id, help: v.help })),
        null,
        2,
      ),
    ).toEqual([]);
  });
}

for (const path of PUBLIC_PATHS) {
  test(`exactly one h1: ${path}`, async ({ page }) => {
    await page.goto(path);
    await expect(page.locator("h1")).toHaveCount(1);
  });
}

test("skip link is reachable by keyboard and moves focus to main", async ({
  page,
}) => {
  await page.goto("/");
  await page.keyboard.press("Tab");
  const skip = page.getByRole("link", { name: /skip to content/i });
  await expect(skip).toBeFocused();
  await skip.press("Enter");
  await expect(page.locator("#main")).toBeFocused();
});

